head.script:
scwin.onpageload = function() {
    // 모달 초기화
    scwin.initModal();
};

// 모달 초기화
scwin.initModal = function() {
    try {
        // 팝업 파라미터에서 teamName 가져오기 - dataObject 방식
        var popupParam = $p.getParameter("project_param");
        var teamName = "식스센스"; // 기본값

        if (popupParam && popupParam.teamName) {
            teamName = popupParam.teamName;
            console.log("팝업 파라미터에서 팀장명 가져옴:", teamName);
        } else {
            console.log("팝업 파라미터가 없어 기본값 사용:", teamName);
        }

        // 기본값 설정
        dm_projectForm.set("projectName", "2차 프로젝트");
        dm_projectForm.set("teamName", teamName);
        dm_projectForm.set("hour", "00");
        dm_projectForm.set("minute", "00");

        // 팀장 인풋을 읽기전용으로 설정
        if (input_teamName) {
            input_teamName.setValue(teamName);
            input_teamName.setReadOnly(true);
        }

        console.log("프로젝트 추가 모달 초기화 완료 - 팀장:", teamName);
    } catch(e) {
        console.error("모달 초기화 오류:", e);
        // 오류 발생 시 기본값 설정
        dm_projectForm.set("projectName", "2차 프로젝트");
        dm_projectForm.set("teamName", "식스센스");
        dm_projectForm.set("hour", "00");
        dm_projectForm.set("minute", "00");

        if (input_teamName) {
            input_teamName.setReadOnly(true);
        }
    }
};

// 모달 닫기
// scwin.closeModal = function() {
//     try {
