//         $p.closePopup();
//         console.log("모달 닫기 완료");
//     } catch(e) {
//         console.error("모달 닫기 오류:", e);
//     }
// };

// 저장 버튼 클릭
scwin.btn_save_onclick = function(e) {
    try {
        let projectName = dm_projectForm.get("projectName");
        let teamName = dm_projectForm.get("teamName");

        if (!projectName || projectName.trim() === "") {
            alert("프로젝트명을 입력해주세요.");
            return;
        }

        if (!teamName || teamName.trim() === "") {
            alert("팀장명을 입력해주세요.");
            return;
        }

        // [수정] 서브미션 실행
        $c.sbm.execute(sbm_saveProject);

    } catch(e) {
        console.error("프로젝트 저장 오류:", e);
        alert("프로젝트 저장 중 오류가 발생했습니다.");
    }
};

// [추가] 서브미션 성공 시 처리
scwin.sbm_saveProject_submitdone = function(e) {
    alert("프로젝트가 성공적으로 저장되었습니다!");
    $p.parent().popup_closeAction();

    // 부모 창의 refreshSideMenu 함수 호출 (필요시 주석 해제)
    var parentFrame = $p.parent();
    if (parentFrame && parentFrame.scwin && parentFrame.scwin.refreshSideMenu) {
        parentFrame.scwin.refreshSideMenu();
    }
};

// [추가] 서브미션 실패 시 처리
scwin.sbm_saveProject_submiterror = function(e) {
    console.error("프로젝트 저장 실패:", e);
    alert("프로젝트 저장 중 오류가 발생했습니다. 다시 시도해주세요.");
};

// 이름 입력 키보드 이벤트
scwin.input_name_onkeyup = function(e) {
    dm_projectForm.set("projectName", e.target.value);
};

// 시간 입력 검증
scwin.validateTimeInput = function(inputValue, maxValue) {
    var num = parseInt(inputValue);
    if (isNaN(num) || num < 0) {
        return "00";
    } else if (num > maxValue) {
        return String(maxValue).padStart(2, '0');
    } else {
        return String(num).padStart(2, '0');
    }
};

// [수정] 시간 입력 키보드 이벤트
scwin.input_hour_onkeyup = function(e) {
    dm_projectForm.set("hour", scwin.validateTimeInput(e.target.value, 23));
};

// [수정] 분 입력 키보드 이벤트
scwin.input_minute_onkeyup = function(e) {
    dm_projectForm.set("minute", scwin.validateTimeInput(e.target.value, 59));
};
